sys_variable_value.value:
(function execute(inputs, outputs) {

var token_primary = inputs.token;
var payload_primary = JSON.parse(inputs.payload);

try {
    var tokenBearer = token_primary;
    var endpoint = getEndpoint() + '/crm/luc';  // Endereço da API do SAP

    // Laço para enviar cada objeto individualmente
    var payloadfim = [];
    for (var i = 0; i < payload_primary.length; i++) {
        var answerObject = payload_primary[i];

        gs.info('***Junção ATT ' + JSON.stringify(answerObject)); // Exibe o objeto sendo processado

        // Criação da requisição para cada item de answerObject
        var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'criarLuc');
        r.setStringParameterNoEscape('token', tokenBearer);

        r.setEndpoint(endpoint);
        r.setRequestHeader('Authorization', 'Bearer ' + tokenBearer);
        r.setRequestHeader('Content-Type', 'application/json');

        // Converte o objeto answerObject para string e adiciona ao corpo da requisição
        var requestBody = JSON.stringify(answerObject);  // Apenas o answerObject
        r.setRequestBody(requestBody);

        gs.info('###Junção ATT Corpo da requisição: POST LUC ' + requestBody);

        // Executa a requisição e captura a resposta
        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        // Analisa o corpo da resposta para verificar o "code"
        var responseParsed = JSON.parse(responseBody);
        var code = responseParsed.code;

        gs.info('Junção ATT ### SAPintegraUtils.postLuc response body: ' + responseBody);
        var lucAnswer = responseParsed.LucKey;
        if (lucAnswer) {
            outputs.luckey = lucAnswer;
            gs.info('***PK LUC: ' + lucAnswer);
            payloadfim.push(outputs.luckey);
        } else {
            outputs.luckey = 'Não cadastrada, consulte as informações ou o ADM do Sistema';
            gs.info('***PK LUC: ' + lucAnswer);
            payloadfim.push(outputs.luckey);
        }

        // Verifica o "code" e o "httpStatus" simultaneamente
        if ((httpStatus == 200 || httpStatus == 201 || httpStatus == 202) &&
            (code == "200" || code == "201" || code == "202")) {

            // Requisição bem-sucedida
            outputs.responsebodyanswer = JSON.stringify({
                http: httpStatus,
                responseBody: responseParsed,
                requestBody: requestBody,
            });
            outputs.answer_script = 'Criação realizada com sucesso'; 
            outputs.http = httpStatus || 'Não há';
            outputs.code = code || 'Não há';
            outputs.description = responseParsed.description || 'Não há';
            outputs.message = responseParsed.message || 'Não há';

            gs.info("###Junção ATT  Requisição bem-sucedida: " + JSON.stringify(outputs));
        } else {
            // Falha devido ao "code" ou "httpStatus"
            gs.info("###Junção ATT  SAPintegraUtils.postLuc STATUS ou CODE inválido. STATUS: " + httpStatus + " CODE: " + code);
            outputs.answer_script = "HTTP Status " + httpStatus + ", Code: " + code + ", Message: " + responseParsed.message + ' LUC CRIADA: ' + lucAnswer;
        }
    }
    
    gs.info('***PK LUC: ' + JSON.stringify(payloadfim));
    var valoresFormatados = payloadfim.map(valor => valor.trim()).join('\n');
    outputs.payloadluckey = valoresFormatados;

} catch (ex) {
    // Tratamento de exceção
    gs.info("###Junção ATT  Erro na requisição: " + ex.message);
    outputs.answer_script = "Catch Erro na Integração: " + ex.message;
}

// Função para obter o endpoint dinâmico com base na instância
function getEndpoint() {
    var instanceName = gs.getProperty('instance_name');

    if (instanceName == 'allos') {
        gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd'));
        return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd');
    } else {
        gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa'));
        return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa');
    }
}



})(inputs, outputs);

